create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.UDF_PROGNOSE_WHATIF (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	ANGEBOT_ID NUMBER(38,0) NOT NULL COMMENT 'Offer/Angebot-ID.',
	DAT_VON DATE COMMENT 'YYYY-MM-DD // Aktion gültig von.',
	DAT_BIS DATE COMMENT 'YYYY-MM-DD // Aktion gültig bis.',
	MENGE_PROGNOSE_BASIS NUMBER(38,5) COMMENT 'Basisverkaufsmenge für zusätzliche Deltaverkaufsberechnungen.',
	MENGE_PROGNOSE_SAISON NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Saisonalität.',
	MENGE_PROGNOSE_FEIERTAG NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Feiertagen.',
	MENGE_PROGNOSE_PREISAENDERUNG NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Preisänderungen.',
	MENGE_PROGNOSE_KAUFANREIZE NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen vorausgesetzten Kaufanreizen.',
	MENGE_PROGNOSE_UPLIFT NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Effekt durch Angebotsart-Uplift.',
	MENGE_PROGNOSE_WERBEMITTEL NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Effekt aller Werbemittel.',
	MENGE_PROGNOSE_PRAEMIENKAUFANREIZE NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Prämienkaufanreizen.',
	MENGE_PROGNOSE_KUNDENKARTE NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Kundenkarte.',
	MENGE_PROGNOSE_VERFUEGBARKEIT NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Verfügbarkeit.',
	MENGE_PROGNOSE_KANNIBALISIERUNG NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Kannibalisierung.',
	MENGE_PROGNOSE_VERBUND NUMBER(38,5) COMMENT 'Nettoverkaufsmenge wegen Verbundeffekt.',
	MENGE_PROGNOSE_FAKTOREN NUMBER(38,5) COMMENT 'Nettoverkaufsmenge aus anderen Bedarfseinflussfaktoren.',
	MENGE_PROGNOSE_GESAMT NUMBER(38,5) COMMENT 'Nettoverkaufsmenge gesamt.',
	DAT_ERSTELLUNG DATE NOT NULL COMMENT 'Anlagedatum aus dat_erstellung.',
	DAT_BELADUNG DATE COMMENT 'Beladungsdatum (DWH).',
	DAT_PROGNOSE_WERBUNG_ZULETZT_GESTEUERT DATE COMMENT 'Datum der letzten manuellen  Prognosesteuerung für die Werbeprognose.',
	PROGNOSE_OFFER_NULLWERT_FG NUMBER(38,0) COMMENT 'Einfluss auf Prognose durch Offer = 0.',
	PROGNOSE_PREIS_NULLWERT_FG NUMBER(38,0) COMMENT 'Einfluss auf Prognose durch Preis = 0.',
	PROGNOSE_PREIS_FAKTOR_FG NUMBER(38,0) COMMENT 'Einfluss auf Prognose durch Preis < 0.',
	PROGNOSE_TACTIC_NULLWERT_FG NUMBER(38,0) COMMENT 'Einfluss auf Prognose durch Tactic = 0.',
	MENGE_PROGNOSE_FAKTOR_FG NUMBER(38,0) COMMENT 'Einfluss aller Faktoren auf die Prognose < 0.',
	MENGE_PROGNOSE_NULLWERT_FG NUMBER(38,0) COMMENT 'Einfluss aller Faktoren auf die Prognose = 0.',
	QUELLE_ALT_PRIOREN_FG NUMBER(38,0) COMMENT 'ACHTUNG: Abgelöst mit der Einführung der ANZ_A_PRIORI_PARAMETER_* Spalten. Nur noch gültig/gefüllt für historische Daten davor. Flag: Sagt aus, ob alternative a-priori Parameter (Prioren) verwendet wurden als die zum Artikel eigenen. Andere sind entweder Referenzartikel, hierarchische Prioren oder global-default Einstellungen. 1 bedeutet, dass mindestens eine der erwähnten Alternativen zur Berechnung der Prognose herangezogen wurde.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	DAT_PROGNOSE_NORMAL_ZULETZT_GESTEUERT DATE COMMENT 'Datum der letzten Prognosesteuerung für die Normalprognose.',
	ANZ_PRIOR_GESAMT NUMBER(38,0) COMMENT 'Anzahl aller verfügbaren Prioren zur Prognoseberechnung. Prior ist die übliche Abkürzung für a priori Wahrscheinlichkeit. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\n            SAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\n            Wenig historische Daten → Parameterschätzungen näher an Priors\n            Viele historische Daten → Parameterschätzungen näher an Daten\n            Die berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_EIGEN NUMBER(38,0) COMMENT 'Anzahl der verfügbaren Prioren, die auf der eigenen Historie basieren. Höchste Präferenz. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\n            SAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\n            Wenig historische Daten → Parameterschätzungen näher an Priors\n            Viele historische Daten → Parameterschätzungen näher an Daten\n            Die berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_REF NUMBER(38,0) COMMENT 'Anzahl der verfügbaren Prioren, die auf der Referenzhistorie basieren. Erst-niedrigere Präferenz, nach den eigenen Prioren. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\n            SAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\n            Wenig historische Daten → Parameterschätzungen näher an Priors\n            Viele historische Daten → Parameterschätzungen näher an Daten\n            Die berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_HPR NUMBER(38,0) COMMENT 'Anzahl der verfügbaren Prioren, die auf hierarchischen Prioren (HPR) basieren (z.B. WG, WUG bzw. WGI (Warengruppenindex)). Hierarchische Kriterien die indirekt zum Artikel gehören, wie z.B. Warengruppe. Zweit-niedrigere Präferenz, nach den eigenen und Referenzartikeln. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\n            SAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\n            Wenig historische Daten → Parameterschätzungen näher an Priors\n            Viele historische Daten → Parameterschätzungen näher an Daten\n            Die berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_DEFAULT NUMBER(38,0) COMMENT 'Anzahl der verfügbaren Prioren, die auf default-Werten basieren. Niedrigste Präferenz, nach den eigenen, Referenzartikeln und hierarchischen Prioren. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\n            SAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\n            Wenig historische Daten → Parameterschätzungen näher an Priors\n            Viele historische Daten → Parameterschätzungen näher an Daten\n            Die berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	DK_FG NUMBER(38,0) COMMENT 'Flag gibt an, ob eine Aktion (Offer) in der UDF-Prognose durch die sogenannte Doorkeeper-Logik herausgefiltert wurde.\n            1 (Ja): Die Aktion wurde durch den Doorkeeper ausgefiltert und ist somit in UDF inaktiv.\n            0 (Nein): Die Aktion wurde nicht ausgefiltert und bleibt in UDF aktiv.\n            Quelle ist das Feld DK_RELEVANCE aus der SAP Tabelle ZUDF_OFRWBS_DATA. Mapping: wenn X=1, sonst 0.',
	constraint PK_UDF_PROGNOSE_WHATIF primary key (MANDANT_ID, WUP_ID, ART_ID, NB_ID, ANGEBOT_ID)
)COMMENT='SCM - Prognosewerte aus SAP UDF - Lookup 00700 = 7 > Lookup_Table L_System\n             Die Tabelle UDF_PROGNOSE_WHATIF enthält eine ursachengerechte Aufschlüsselung für die errechneten Werbeprognosen aus dem SAP-Quellsystem UDF.\n             Die Prognose wird unter Berücksichtigung unterschiedlicher Einflüsse, wie z.B. Saisonalität (menge_prognose_saison) oder Kannibalisierung mit anderen Artikeln (menge_prognose_kannibalisierung) gebildet. Die Aufschlüsselung auf die einzelnen Einflussfaktoren ermöglicht dem User ein besseres Verständnis darüber, wie sich die Prognose gebildet hat und erlaubt Rückschlüsse auf die Steuerung dieser.\n             Die Prioren-Felder enthalten Informationen darüber, auf welcher Basis sich die Prognose gebildet hat – entfällt beispielsweise ein großer Anteil der Prioren auf den Referenzartikel (anz_prioren_referenz), so kann der User daraus ableiten, dass kaum die Historie des eigenen Artikels herangezogen wurde. Eine gewünschte Veränderung der Prognose durch den User kann so z.B. über die Änderung des Referenzartikels herbeigeführt werden.\n             Des Weiteren enthält die Tabelle auch Informationen über den letzten manuellen Eingriff durch den User (dat_prognose_zuletzt_gesteuert).'
;
